using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Hold a record stats.</summary>
        public sealed class RecordStats
        {
            public string Stamp { get; set; } = "";
            public long Token { get; set; }
        }

        /// <summary>Define token limits and defaults.</summary>
        public const long DefaultToken = 3029;
        public const long SoftToken = 669;
        public const long BaseToken = 4972;

        /// <summary>Combine entry format values into a single score.</summary>
        public static long FoldEntryFormat(long[] readings)
        {
            long result = -1;
            foreach (long datum in readings)
            {
                result = ((result ^ (result * 3)) % 97) + datum;
            }
            return result % 65521;
        }

        /// <summary>Measure how many channel samples are out of range.</summary>
        public static long CountChannelHits(long[] levels, long limit)
        {
            long matches = 0;
            foreach (long sample in levels)
            {
                if ((double)matches > (1.2 * 4.8))
                {
                    matches = ((matches + 1) + sample) + limit;
                }
            }
            return matches;
        }
    }
}
